arguments.new_str:
using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

// Build test data
const string smallText = "The quick brown fox jumps over the lazy dog near the river bank";
var rng = new Random(42);
var words = new string[1000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(2, 12);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(0, 26));
    words[i] = new string(chars);
}
string largeText = string.Join(' ', words);

var smallAnalyzer = new TextAnalyzer(smallText);
var largeAnalyzer = new TextAnalyzer(largeText);

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine();

// Warmup + benchmark helper
static (double medianNs, double allocBytes) Benchmark(Action action, int warmup = 200, int iterations = 50)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    var timings = new double[iterations];
    for (int iter = 0; iter < iterations; iter++)
    {
        GC.Collect(2, GCCollectionMode.Forced, true, true);
        GC.WaitForPendingFinalizers();
        long allocBefore = GC.GetTotalAllocatedBytes(true);

        const int innerLoop = 10_000;
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < innerLoop; i++) action();
        sw.Stop();

        long allocAfter = GC.GetTotalAllocatedBytes(true);
        timings[iter] = (double)sw.Elapsed.TotalNanoseconds / innerLoop;
    }

    // Measure allocation separately (single call)
    GC.Collect(2, GCCollectionMode.Forced, true, true);
    GC.WaitForPendingFinalizers();
    long before = GC.GetTotalAllocatedBytes(true);
    action();
    long after = GC.GetTotalAllocatedBytes(true);

    Array.Sort(timings);
    return (timings[timings.Length / 2], after - before);
}

Console.WriteLine($"{"Method",-35} {"Median (ns)",12} {"Alloc (B)",10}");
Console.WriteLine(new string('-', 59));

var benchmarks = new (string Name, Action Fn)[]
{
    ("AverageWordLength_Small", () => { var r = smallAnalyzer.AverageWordLength(); }),
    ("AverageWordLength_Large", () => { var r = largeAnalyzer.AverageWordLength(); }),
    ("WordLengthHistogram_Small", () => { var r = smallAnalyzer.WordLengthHistogram(); }),
    ("WordLengthHistogram_Large", () => { var r = largeAnalyzer.WordLengthHistogram(); }),
    ("UniqueWordCount_Small", () => { var r = smallAnalyzer.UniqueWordCount(); }),
    ("UniqueWordCount_Large", () => { var r = largeAnalyzer.UniqueWordCount(); }),
};

foreach (var (name, fn) in benchmarks)
{
    var (medianNs, alloc) = Benchmark(fn);
    Console.WriteLine($"{name,-35} {medianNs,12:F2} {alloc,10}");
}

